import time
import numpy as np
from scipy.optimize import minimize

N = 16
IU, JU = np.triu_indices(N, 1)
K = len(IU)
ROWS = np.arange(K)
OBJ = np.zeros(2 * N + 1)
OBJ[-1] = 1.0


def _score(P):
    if P is None:
        return np.inf
    P = np.asarray(P, dtype=float)
    if P.shape != (N, 2) or not np.all(np.isfinite(P)):
        return np.inf
    d2 = np.sum((P[IU] - P[JU]) ** 2, axis=1)
    mn = d2.min()
    if mn <= 1e-12:
        return np.inf
    return d2.max() / mn


def _riesz(x, p):
    # Riesz s-energy sum d^-p with analytic gradient; drives points apart smoothly.
    diff = x.reshape(N, 2)[IU] - x.reshape(N, 2)[JU]
    d2 = np.maximum(np.sum(diff * diff, axis=1), 1e-12)
    E = np.sum(d2 ** (-p / 2.0))
    g = (-p * d2 ** (-p / 2.0 - 1.0))[:, None] * diff
    G = np.zeros((N, 2))
    np.add.at(G, IU, g)
    np.add.at(G, JU, -g)
    return E, G.reshape(-1)


def _anneal(x, ps):
    # Continuation: raise the exponent so the energy approaches a max-min distance objective.
    x = np.asarray(x, dtype=float).reshape(-1)
    for p in ps:
        P = x.reshape(N, 2)
        d2 = np.sum((P[IU] - P[JU]) ** 2, axis=1)
        x = x / np.sqrt(max(d2.min(), 1e-12))
        x = minimize(_riesz, x, args=(p,), jac=True, method="L-BFGS-B",
                     options={"maxiter": 500}).x
    return x.reshape(N, 2)


def _d2(x):
    diff = x.reshape(N, 2)[IU] - x.reshape(N, 2)[JU]
    return np.sum(diff * diff, axis=1)


def _D(x):
    # Jacobian of squared pair distances w.r.t. coordinates.
    diff = x.reshape(N, 2)[IU] - x.reshape(N, 2)[JU]
    D = np.zeros((K, 2 * N))
    for c in range(2):
        D[ROWS, 2 * IU + c] = 2.0 * diff[:, c]
        D[ROWS, 2 * JU + c] = -2.0 * diff[:, c]
    return D


def _polish(P):
    # Exact SLSQP: minimize s subject to 1 <= pair d2 <= s.
    x0 = np.asarray(P, dtype=float).reshape(-1)
    x0 = x0 / np.sqrt(max(_d2(x0).min(), 1e-12))
    z0 = np.concatenate([x0, [_d2(x0).max()]])

    def cons(z):
        d = _d2(z[:-1])
        return np.concatenate([z[-1] - d, d - 1.0])

    def jac(z):
        D = _D(z[:-1])
        top = np.hstack([-D, np.ones((K, 1))])
        bot = np.hstack([D, np.zeros((K, 1))])
        return np.vstack([top, bot])

    res = minimize(lambda z: z[-1], z0, jac=lambda z: OBJ, method="SLSQP",
                   constraints=[{"type": "ineq", "fun": cons, "jac": jac}],
                   options={"maxiter": 300, "ftol": 1e-13})
    return res.x[:-1].reshape(N, 2)


def solve(time_limit, best_so_far):
    t0 = time.time()
    budget = min(0.5 * float(time_limit), 8.0)
    rng = np.random.default_rng()

    best_P, best_s = None, np.inf
    if best_so_far is not None:
        P = np.asarray(best_so_far, dtype=float)
        s = _score(P)
        if np.isfinite(s):
            best_P, best_s = P.copy(), s

    while time.time() - t0 < budget:
        try:
            if best_P is not None and rng.random() < 0.3:
                # Local restart: reheat the incumbent at high exponents only.
                start = best_P + rng.normal(0.0, 0.1, (N, 2))
                P = _polish(_anneal(start, (15.0, 40.0)))
            else:
                start = rng.uniform(0.0, 4.0, (N, 2))
                P = _polish(_anneal(start, (2.0, 6.0, 15.0, 40.0)))
        except Exception:
            continue
        s = _score(P)
        if s < best_s - 1e-12:
            best_P, best_s = P.copy(), s

    if best_P is None:
        return np.array([(i, j) for i in range(4) for j in range(4)], dtype=float)
    return best_P


if __name__ == "__main__":
    out = solve(4, None)
    assert out.shape == (N, 2)
    assert _score(out) < 18.0
    print("ratio^2 =", _score(out))
